def block(d, lang):
    return ''.join('    ' + json.dumps(k, ensure_ascii=False) + ': ' + json.dumps(v[lang], ensure_ascii=False) + ',\n' for k, v in d.items())

for lang in ['en', 'hi', 'ta', 'te', 'kn', 'ml']:
    p = f'src/locales/{lang}.json'
    s = open(p, encoding='utf-8', newline=None).read()
    # drop the old single "unavailable" line (it follows securePowered) and add the payment keys there
    s, n = re.subn(r'(    "securePowered": [^\n]*\n)    "unavailable": [^\n]*\n', lambda m: m.group(1) + block(Y, lang), s, count=1)
    assert n == 1, (lang, 'payment')
    s, n = re.subn(r'(    "perYear": [^\n]*\n)', lambda m: m.group(1) + block(P, lang), s, count=1)
    assert n == 1, (lang, 'pricing')
    json.loads(s)
    open(p, 'w', encoding='utf-8', newline='\n').write(s)
print('ok')
